export const userIntegrations = pgTable(
  'user_integrations',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** e.g. 'gcal', 'foreflight', 'stripe' */
    integrationType: text('integration_type').notNull(),
    /** OAuth tokens, API keys, etc. (e.g. KV_GCalTokens) */
    tokenData: jsonb('token_data'),
    /** User-facing settings for the integration (e.g. KV_GCalSettings) */
    settings: jsonb('settings'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    updatedAt: timestamp('updated_at').notNull().defaultNow(),
  },
  (table) => ({
    userTypeIdx: index('user_integrations_user_type_idx').on(
      table.userId,
      table.integrationType,
    ),
    userTypeUnique: index('user_integrations_user_type_unique').on(
      table.userId,
      table.integrationType,
    ),
  }),
);

export type UserIntegration = typeof userIntegrations.$inferSelect;
export type NewUserIntegration = typeof userIntegrations.$inferInsert;

