/**
 * School-owned Stripe integration credentials.
 *
 * This is the authoritative Stripe surface for a flight school's students. It
 * is intentionally separate from Hilo's platform Stripe billing customer and
 * from the deprecated Connect fields on `flight_schools`.
 */
export const schoolStripeIntegrations = pgTable(
  'school_stripe_integrations',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    flightSchoolId: uuid('flight_school_id')
      .notNull()
      .references(() => flightSchools.id, { onDelete: 'cascade' }),
    mode: text('mode').notNull().default('restricted_key'),
    stripeAccountId: text('stripe_account_id'),
    livemode: boolean('livemode').notNull().default(true),
    restrictedKeyEncrypted: text('restricted_key_encrypted'),
    restrictedKeyLastFour: text('restricted_key_last_four'),
    webhookSecretEncrypted: text('webhook_secret_encrypted'),
    webhookSecretLastFour: text('webhook_secret_last_four'),
    connectedByUserId: uuid('connected_by_user_id').references(() => users.id, {
      onDelete: 'set null',
    }),
    connectedAt: timestamp('connected_at'),
    deauthorizedAt: timestamp('deauthorized_at'),
    lastHealthCheckAt: timestamp('last_health_check_at'),
    lastHealthCheckStatus: text('last_health_check_status'),
    lastHealthCheckError: text('last_health_check_error'),
    metadata: jsonb('metadata').notNull().default({}),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    updatedAt: timestamp('updated_at').notNull().defaultNow(),
  },
  (table) => ({
    schoolUnique: uniqueIndex('school_stripe_integrations_school_uniq').on(
      table.flightSchoolId,
    ),
    accountIdx: index('school_stripe_integrations_account_idx').on(
      table.stripeAccountId,
    ),
    healthIdx: index('school_stripe_integrations_health_idx').on(
      table.lastHealthCheckStatus,
      table.lastHealthCheckAt,
    ),
  }),
);

export type SchoolStripeIntegration =
  typeof schoolStripeIntegrations.$inferSelect;
export type NewSchoolStripeIntegration =
  typeof schoolStripeIntegrations.$inferInsert;

