/**
 * Append-only audit trail for every write to users.stripe_customer_id.
 * Every link / force_create / unlink / sweep event lands here so we can
 * answer "who mapped this student and why" without grepping logs.
 */
export const stripeSyncAudit = pgTable(
  'stripe_sync_audit',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    studentId: uuid('student_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** Null when the action was performed by a cron / system sweep. */
    adminUserId: uuid('admin_user_id').references(() => users.id, {
      onDelete: 'set null',
    }),
    /** 'link' | 'create' | 'force_create' | 'unlink' | 'validate' | 'sweep_flag' */
    action: text('action').notNull(),
    stripeCustomerId: text('stripe_customer_id'),
    stripeAccountId: text('stripe_account_id'),
    /** For force_create: typed reason enum. For sweep_flag: the finding. */
    reason: text('reason'),
    /** Candidate customers returned to the admin at decision time. */
    candidates: jsonb('candidates'),
    /** Free-form context (validate status, error messages, etc.) */
    metadata: jsonb('metadata'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    /** Multi-tenant scope — backfilled from students.flight_school_id. */
    flightSchoolId: uuid('flight_school_id').references(
      () => flightSchools.id,
      { onDelete: 'set null' },
    ),
  },
  (table) => ({
    studentIdx: index('idx_stripe_sync_audit_student_id').on(
      table.studentId,
      table.createdAt,
    ),
    actionIdx: index('idx_stripe_sync_audit_action').on(
      table.action,
      table.createdAt,
    ),
    schoolIdx: index('idx_stripe_sync_audit_school').on(
      table.flightSchoolId,
      table.createdAt,
    ),
  }),
);

export type StripeSyncAudit = typeof stripeSyncAudit.$inferSelect;
export type NewStripeSyncAudit = typeof stripeSyncAudit.$inferInsert;

/**
 * One row per customer discovered on a school's Stripe Connect account during
 * post-OAuth reconciliation. Seeded by `reconcileStripeAccount` and surfaced
 * in the admin "Stripe Customers" tab so unmatched Stripe customers get
 * manually linked to ATOS students instead of auto-orphaning onto Hilo's
 * platform account (the 2026-04-20 / -24 incident pattern).
 *
 * status:
 *   'pending'   — no automatic match OR match conflicts with an existing
 *                 stripe_customer_id on the user; admin must resolve
 *   'linked'    — user.stripe_customer_id has been set to this customer
 *   'dismissed' — admin explicitly ignored (e.g. test customer, ex-student)
 *
 * match_confidence:
 *   'exact_email' — users row with matching flight_school_id + email found
 *   'manual'      — admin picked the student via PATCH /reconciliation/:id
 *   'none'        — no ATOS user matched
 */
export const stripeReconciliation = pgTable(
  'stripe_reconciliation',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    flightSchoolId: uuid('flight_school_id')
      .notNull()
      .references(() => flightSchools.id),
    stripeCustomerId: text('stripe_customer_id').notNull(),
    stripeCustomerEmail: text('stripe_customer_email'),
    stripeCustomerName: text('stripe_customer_name'),
    matchedUserId: uuid('matched_user_id').references(() => users.id, {
      onDelete: 'set null',
    }),
    matchConfidence: text('match_confidence'),
    status: text('status').notNull().default('pending'),
    createdAt: timestamp('created_at').notNull().defaultNow(),
    updatedAt: timestamp('updated_at').notNull().defaultNow(),
  },
  (table) => ({
    uniqueSchoolCustomer: uniqueIndex(
      'stripe_reconciliation_school_customer_uniq',
    ).on(table.flightSchoolId, table.stripeCustomerId),
    statusIdx: index('stripe_reconciliation_status_idx').on(
      table.flightSchoolId,
      table.status,
    ),
  }),
);

export type StripeReconciliation = typeof stripeReconciliation.$inferSelect;
export type NewStripeReconciliation = typeof stripeReconciliation.$inferInsert;

